-- Nova, migration 003: real Telegram gift collections (plushpepe..trappedheart).
-- Real attributes with real rarity percentages, real edition numbers and official
-- renders from nft.fragment.com. Upgrade picks a REAL instance from the pool.
-- Pool format: jsonb array of [num, model, backdrop, symbol]; the render URL is
-- derived as gift/<slug>-<num>.webp (verified pattern for all instances).
-- Run whole file in Supabase -> SQL Editor -> Run. Idempotent.
-- NOTE: wipes the old test catalog and test gifts (they were demo-only).

-- ============ schema ============
alter table public.gift_types add column if not exists pool jsonb;
alter table public.gift_types add column if not exists cover text;
alter table public.user_gifts add column if not exists asset text;

-- weights are real instance counts (can exceed 10000 on big collections)
alter table public.gift_attrs drop constraint if exists gift_attrs_weight_check;
alter table public.gift_attrs add constraint gift_attrs_weight_check check (weight between 1 and 100000000);

-- ============ drop old demo catalog ============
delete from public.messages where kind = 'gift';
delete from public.user_gifts;
delete from public.gift_attrs;
delete from public.gift_types where slug in ('plasma_heart','cake','nova_star','rocket','teddy','gold_rose','comet','diamond','crown','cosmos_cube');

